import{D as e,f as t,j as n,m as r,p as i,s as a,u as o}from"./runtime-core.esm-bundler-D3eD_xTR.js";import{t as s}from"./app-BE_K1prB.js";var c=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S02/S02E16.html","title":"S02E16 The One Where Joey Moves Out","lang":"zh-CN","frontmatter":{"title":"S02E16 The One Where Joey Moves Out","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":40},"git":{"createdTime":1780654155000,"updatedTime":1785393428000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":2}]},"readingTime":{"minutes":30.45,"words":9134},"filePathRelative":"语言/英语/Friends老友记/S02/S02E16.md"}`),l={name:`S02E16.md`};function u(s,c,l,u,d,f){let p=n(`AudioButton`);return e(),o(`div`,null,[c[0]||=t(`<h1 id="the-one-where-joey-moves-out" tabindex="-1"><a class="header-anchor" href="#the-one-where-joey-moves-out"><span>The One Where Joey Moves Out</span></a></h1><blockquote><p><em>乔伊搬出去的那一集</em></p></blockquote><p>The One Where Joey Moves Out</p><blockquote><p>乔伊搬出去的那个</p></blockquote><p>Originally written by Betsy Bornes</p><blockquote><p>最初由贝齐·伯恩斯撰写</p></blockquote><p>Transcribed by Joshua Hodge.</p><blockquote><p>由约书亚·霍奇转录。</p></blockquote><p>Minor additions and adjustments by Dan Silverstein.</p><blockquote><p>Dan Silverstein的轻微添加和调整。</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s apartment. Chandler and Joey are sitting at the bar, in their bathrobes, eating cereal</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的公寓。钱德勒和乔伊穿着浴袍坐在酒吧里吃麦片</em></p></blockquote>`,13),r(p,{src:`/audio/friends/S02/S02E16/001.mp3`}),c[1]||=i(),c[2]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[3]||=i(` Man this is weird. You ever realize Captain Crunch's eyebrows are actually on his hat?`,-1),c[4]||=a(`blockquote`,null,[a(`p`,null,`伙计，这太奇怪了。你有没有意识到克朗奇船长的眉毛其实在他的帽子上？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/002.mp3`}),c[5]||=i(),c[6]||=a(`strong`,null,`CHANDLER BING:`,-1),c[7]||=i(` That's what's weird? Joey, the man's been captain of a cereal for the last 40 years.`,-1),c[8]||=a(`blockquote`,null,[a(`p`,null,`这就是奇怪的地方？乔伊，这个人在过去的40年里一直是一种麦片粥的船长。`)],-1),c[9]||=a(`p`,null,`[Joey finishes his cereal, licks his spoon, and puts it back in the silverware drawer.]`,-1),c[10]||=a(`blockquote`,null,[a(`p`,null,`[乔伊吃完麦片粥，舔了舔汤匙，然后把它放回银器抽屉。]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/003.mp3`}),c[11]||=i(),c[12]||=a(`strong`,null,`CHANDLER BING:`,-1),c[13]||=i(` Waaa-aaah.`,-1),c[14]||=a(`blockquote`,null,[a(`p`,null,`哇，啊。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/004.mp3`}),c[15]||=i(),c[16]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[17]||=i(` What?`,-1),c[18]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/005.mp3`}),c[19]||=i(),c[20]||=a(`strong`,null,`CHANDLER BING:`,-1),c[21]||=i(` The spoon. You licked and-and you put. You licked and you put.`,-1),c[22]||=a(`blockquote`,null,[a(`p`,null,`勺子。你舔了舔，然后把它放了。你舔了舔，然后放了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/006.mp3`}),c[23]||=i(),c[24]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[25]||=i(` Yeah, so.`,-1),c[26]||=a(`blockquote`,null,[a(`p`,null,`是的，所以。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/007.mp3`}),c[27]||=i(),c[28]||=a(`strong`,null,`CHANDLER BING:`,-1),c[29]||=i(` Well don't you see how gross that is? I mean that's like you using my toothbrush. [Joey gets a sheepish look] You used my toothbrush?`,-1),c[30]||=a(`blockquote`,null,[a(`p`,null,`你没看到这有多恶心吗？我是说就像你用我的牙刷一样。你用了我的牙刷？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/008.mp3`}),c[31]||=i(),c[32]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[33]||=i(` Well, that was only 'cause I used the red one to unclog the drain.`,-1),c[34]||=a(`blockquote`,null,[a(`p`,null,`嗯，那只是因为我用红色的那个疏通了下水道。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/009.mp3`}),c[35]||=i(),c[36]||=a(`strong`,null,`CHANDLER BING:`,-1),c[37]||=i(` Mine is the red one! Oh God. Can open, worms everywhere.`,-1),c[38]||=a(`blockquote`,null,[a(`p`,null,`我的是红色的！哦，上帝。可以打开，蠕虫无处不在。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/010.mp3`}),c[39]||=i(),c[40]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[41]||=i(` Hey, why can't we use the same toothbrush, but we can use the same soap?`,-1),c[42]||=a(`blockquote`,null,[a(`p`,null,`嘿，为什么我们不能用同样的牙刷，但我们可以用同样的肥皂？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/011.mp3`}),c[43]||=i(),c[44]||=a(`strong`,null,`CHANDLER BING:`,-1),c[45]||=i(` Because soap is soap. It's self-cleaning.`,-1),c[46]||=a(`blockquote`,null,[a(`p`,null,`因为肥皂就是肥皂。它是自动清洗的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/012.mp3`}),c[47]||=t(` <strong>JOEY TRIBBIANI:</strong> Alright, well next time you take a shower, think about the last thing I wash and the first thing you wash.<blockquote><p>好吧，下次你洗澡的时候，想想我最后洗的东西和你第一次洗的东西。</p></blockquote><p>OPENING TITLES</p><blockquote><p>开场白</p></blockquote><hr><p>🎬 <em>Monica and Rachel&#39;s apartment. Monica and Phoebe are sitting at the table, Joey and Chandler enter.</em></p><blockquote><p>🎬 <em>莫妮卡和瑞秋的公寓。莫妮卡和菲比坐在桌子旁，乔伊和钱德勒进来。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S02/S02E16/013.mp3`}),c[48]||=i(),c[49]||=a(`strong`,null,`CHANDLER BING:`,-1),c[50]||=i(` Hey.`,-1),c[51]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),c[52]||=a(`p`,null,`MONICA and **Phoebe Buffay: **Hey.`,-1),c[53]||=a(`blockquote`,null,[a(`p`,null,[i(`莫妮卡和`),a(`strong`,null,`菲比·布菲：`),i(`嘿。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/014.mp3`}),c[54]||=i(),c[55]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[56]||=i(` Hey.`,-1),c[57]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/015.mp3`}),c[58]||=i(),c[59]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[60]||=i(` Ooh, look at you fancy lads. What's the occasion?`,-1),c[61]||=a(`blockquote`,null,[a(`p`,null,`哦，看看你们这些花花公子。什么场合？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/016.mp3`}),c[62]||=i(),c[63]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[64]||=i(` Well, you know that guy that's on my show that's in a coma? He's havin' a brunch.`,-1),c[65]||=a(`blockquote`,null,[a(`p`,null,`你知道我节目里那个昏迷的家伙吗？他正在吃早午餐。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/017.mp3`}),c[66]||=i(),c[67]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[68]||=i(` Ahh.`,-1),c[69]||=a(`blockquote`,null,[a(`p`,null,`啊。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/018.mp3`}),c[70]||=i(),c[71]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[72]||=i(` [enters from her room] OK, ready when you are.`,-1),c[73]||=a(`blockquote`,null,[a(`p`,null,`（从她的房间进来）好的，准备好了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/019.mp3`}),c[74]||=i(),c[75]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[76]||=i(` Okey-doke.`,-1),c[77]||=a(`blockquote`,null,[a(`p`,null,`好的，多克。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/020.mp3`}),c[78]||=i(),c[79]||=a(`strong`,null,`MONICA GELLER:`,-1),c[80]||=i(` I can't believe you guys are actually getting tattoos.`,-1),c[81]||=a(`blockquote`,null,[a(`p`,null,`真不敢相信你们居然纹身了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/021.mp3`}),c[82]||=i(),c[83]||=a(`strong`,null,`CHANDLER BING:`,-1),c[84]||=i(` Excuse me, you guys are getting tattoos?`,-1),c[85]||=a(`blockquote`,null,[a(`p`,null,`对不起，你们要纹身吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/022.mp3`}),c[86]||=i(),c[87]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[88]||=i(` Yes, but you can not tell Ross 'cause I want to surprise him.`,-1),c[89]||=a(`blockquote`,null,[a(`p`,null,`是的，但你不能告诉罗斯，因为我想给他一个惊喜。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/023.mp3`}),c[90]||=i(),c[91]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[92]||=i(` Wow, this is wild. What're you gonna get?`,-1),c[93]||=a(`blockquote`,null,[a(`p`,null,`哇，这太疯狂了。你会得到什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/024.mp3`}),c[94]||=i(),c[95]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[96]||=i(` Um, I'm getting a lily for my Mom. 'Cause her name's Lily.`,-1),c[97]||=a(`blockquote`,null,[a(`p`,null,`嗯，我要给我妈妈买一朵百合花因为她叫莉莉。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/025.mp3`}),c[98]||=i(),c[99]||=a(`strong`,null,`CHANDLER BING:`,-1),c[100]||=i(` Wow, that's lucky. What if her name was Big Ugly Splotch?`,-1),c[101]||=a(`blockquote`,null,[a(`p`,null,`哇，真幸运。如果她的名字是又大又丑的斑点呢？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/026.mp3`}),c[102]||=i(),c[103]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[104]||=i(` So where you gettin' it?`,-1),c[105]||=a(`blockquote`,null,[a(`p`,null,`那你从哪儿弄来的？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/027.mp3`}),c[106]||=i(),c[107]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[108]||=i(` I think on my shoulder. [Ross enters]`,-1),c[109]||=a(`blockquote`,null,[a(`p`,null,`我想在我的肩膀上。[罗斯进来]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/028.mp3`}),c[110]||=i(),c[111]||=a(`strong`,null,`ROSS GELLER:`,-1),c[112]||=i(` What? What's on your shoulder?`,-1),c[113]||=a(`blockquote`,null,[a(`p`,null,`什么？你肩上有什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/029.mp3`}),c[114]||=i(),c[115]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[116]||=i(` Um, a chip. A tattoo, I'm getting a tattoo.`,-1),c[117]||=a(`blockquote`,null,[a(`p`,null,`嗯，一块芯片。纹身，我要纹身了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/030.mp3`}),c[118]||=i(),c[119]||=a(`strong`,null,`ROSS GELLER:`,-1),c[120]||=i(` A tattoo? Why, why would you want to do that? [to Rachel] Hi.`,-1),c[121]||=a(`blockquote`,null,[a(`p`,null,`纹身？为什么，你为什么要这么做？[对瑞秋]嗨。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/031.mp3`}),c[122]||=i(),c[123]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[124]||=i(` Hi. Well hey, you don't - you don't think they're kind of cool?`,-1),c[125]||=a(`blockquote`,null,[a(`p`,null,`嗨。嘿，你不觉得他们很酷吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/032.mp3`}),c[126]||=i(),c[127]||=a(`strong`,null,`ROSS GELLER:`,-1),c[128]||=i(` No, sorry I don't. Tell me why would anyone pay someone to scar their body for life? What if it doesn't come out right Phoebe? Then it's like, I don't know, havin' a bad hair cut all the time. Why's everyone staring at me?`,-1),c[129]||=a(`blockquote`,null,[a(`p`,null,`不，对不起，我没有。告诉我，为什么会有人付钱给某人，让他终生留下伤疤？菲比，如果结果不好呢？然后就好像，我不知道，一直剪着一头糟糕的头发。为什么大家都盯着我看？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/033.mp3`}),c[130]||=i(),c[131]||=a(`strong`,null,`MONICA GELLER:`,-1),c[132]||=i(` Ross, come sign this birthday card for dad. Rich is gonna be here any minute.`,-1),c[133]||=a(`blockquote`,null,[a(`p`,null,`罗斯，来给爸爸签这张生日卡。里奇随时都会来。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/034.mp3`}),c[134]||=i(),c[135]||=a(`strong`,null,`CHANDLER BING:`,-1),c[136]||=i(` Oooh, Rich is goin' to the party too, huh?`,-1),c[137]||=a(`blockquote`,null,[a(`p`,null,`哦，里奇也要去参加派对，是吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/035.mp3`}),c[138]||=i(),c[139]||=a(`strong`,null,`MONICA GELLER:`,-1),c[140]||=i(` Well, he's my parents' best friend, he has to be there.`,-1),c[141]||=a(`blockquote`,null,[a(`p`,null,`嗯，他是我父母最好的朋友，他必须在那里。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/036.mp3`}),c[142]||=i(),c[143]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[144]||=i(` Oh, is today the day you're gonna tell them about you two?`,-1),c[145]||=a(`blockquote`,null,[a(`p`,null,`哦，今天是你告诉他们你们俩的日子吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/037.mp3`}),c[146]||=i(),c[147]||=a(`strong`,null,`MONICA GELLER:`,-1),c[148]||=i(` Yeah. It's my dad's birthday, I decided to give him a stroke.`,-1),c[149]||=a(`blockquote`,null,[a(`p`,null,`是的。今天是我爸爸的生日，我决定给他打一针。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/038.mp3`}),c[150]||=i(),c[151]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[152]||=i(` No, I think you should tell them.`,-1),c[153]||=a(`blockquote`,null,[a(`p`,null,`不，我想你应该告诉他们。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/039.mp3`}),c[154]||=i(),c[155]||=a(`strong`,null,`MONICA GELLER:`,-1),c[156]||=i(` No, I don't even know how serious he is about me. Until I do, I'm not telling them anything.`,-1),c[157]||=a(`blockquote`,null,[a(`p`,null,`不，我甚至不知道他对我有多认真。在我这么做之前，我不会告诉他们任何事情。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/040.mp3`}),c[158]||=i(),c[159]||=a(`strong`,null,`ROSS GELLER:`,-1),c[160]||=i(` I don't know, I don't think mom and dad would mind. Remember when you were 9 and Richard was 30, how dad used to say, 'God I hope they get together.'`,-1),c[161]||=a(`blockquote`,null,[a(`p`,null,`我不知道，我想爸爸妈妈不会介意的。还记得你9岁，理查德30岁时，爸爸常说，‘上帝啊，我希望他们能在一起。’`)],-1),c[162]||=a(`hr`,null,null,-1),c[163]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The Gellers' house. Monica, Ross, and Richard are arriving to Mr. Gellers birthday party.`)],-1),c[164]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`盖勒家。莫妮卡、罗斯和理查德要来参加盖勒先生的生日聚会。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/041.mp3`}),c[165]||=i(),c[166]||=a(`strong`,null,`ROSS GELLER:`,-1),c[167]||=i(` Alright, shall we?`,-1),c[168]||=a(`blockquote`,null,[a(`p`,null,`好的，好吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/042.mp3`}),c[169]||=i(),c[170]||=a(`strong`,null,`MONICA GELLER:`,-1),c[171]||=i(` OK, wait, wait, wait, wait. You know what? Ross, let's - let's switch places. You get in the middle. No un-, ya know, unless this looks like we're trying to cover something up.`,-1),c[172]||=a(`blockquote`,null,[a(`p`,null,`好的，等等，等等，等等。你知道吗？罗斯，换个位置吧。你在中间。不，你知道，除非这看起来像是我们在掩盖什么。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/043.mp3`}),c[173]||=i(),c[174]||=a(`strong`,null,`ROSS GELLER:`,-1),c[175]||=i(` Monica, Monica, you could come in straddling him, they still wouldn't believe it. [opens door] We're here.`,-1),c[176]||=a(`blockquote`,null,[a(`p`,null,`莫妮卡，莫妮卡，你可以跨着他进来，他们还是不相信。[开门]我们到了。`)],-1),c[177]||=a(`p`,null,`MRS. GELLER: Oh hi kids. Hi darling.`,-1),c[178]||=a(`blockquote`,null,[a(`p`,null,`噢，嗨，孩子们。嗨，亲爱的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/044.mp3`}),c[179]||=i(),c[180]||=a(`strong`,null,`MONICA GELLER:`,-1),c[181]||=i(` Happy birthday dad.`,-1),c[182]||=a(`blockquote`,null,[a(`p`,null,`生日快乐，爸爸。`)],-1),c[183]||=a(`p`,null,`MR. GELLER: Oh thank you.`,-1),c[184]||=a(`blockquote`,null,[a(`p`,null,`哦，谢谢。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/045.mp3`}),c[185]||=i(),c[186]||=a(`strong`,null,`ROSS GELLER:`,-1),c[187]||=i(` Hi ma.`,-1),c[188]||=a(`blockquote`,null,[a(`p`,null,`嗨，妈。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/046.mp3`}),c[189]||=i(),c[190]||=a(`strong`,null,`RICHARD:`,-1),c[191]||=i(` Happy birthday.`,-1),c[192]||=a(`blockquote`,null,[a(`p`,null,`生日快乐。`)],-1),c[193]||=a(`p`,null,`MRS. GELLER: Well, you kids thank Dr. Burke for the ride?`,-1),c[194]||=a(`blockquote`,null,[a(`p`,null,`好吧，你们这些孩子感谢伯克博士的搭车？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/047.mp3`}),c[195]||=i(),c[196]||=a(`strong`,null,`ROSS GELLER:`,-1),c[197]||=i(` Uh, actually mom, I think Monica thanked him for the both of us.`,-1),c[198]||=a(`blockquote`,null,[a(`p`,null,`嗯，事实上，妈妈，我想莫妮卡为我们俩感谢了他。`)],-1),c[199]||=a(`hr`,null,null,-1),c[200]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`The Gellers' kitchen. Monica, Mrs. Geller and one of Mrs. Geller's friends are preparing the cake.`)],-1),c[201]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`盖勒家的厨房。莫妮卡、盖勒太太和盖勒太太的一个朋友正在准备蛋糕。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/048.mp3`}),c[202]||=i(),c[203]||=a(`strong`,null,`FRIEND:`,-1),c[204]||=i(` Well, you kids take the train in?`,-1),c[205]||=a(`blockquote`,null,[a(`p`,null,`你们这些孩子坐火车进去吗？`)],-1),c[206]||=a(`p`,null,`MRS. GELLER: No, Richard Burke gave them a ride.`,-1),c[207]||=a(`blockquote`,null,[a(`p`,null,`不，理查德·伯克载他们一程。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/049.mp3`}),c[208]||=i(),c[209]||=a(`strong`,null,`FRIEND:`,-1),c[210]||=i(` Oh. Speaking of whom, I hear he's got some 20-year-old twinkie in the city. [Monica sprays whipped cream all over the place]`,-1),c[211]||=a(`blockquote`,null,[a(`p`,null,`哦。说到谁，我听说他在城里养了个20岁的双胞胎。[莫妮卡把鲜奶油喷得到处都是]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/050.mp3`}),c[212]||=i(),c[213]||=a(`strong`,null,`MONICA GELLER:`,-1),c[214]||=i(` Finger cramp. Oh God, sorry. Here, let me get that mom.`,-1),c[215]||=a(`blockquote`,null,[a(`p`,null,`手指抽筋。哦，天哪，对不起。来，让我去找那个妈妈。`)],-1),c[216]||=a(`p`,null,`MRS. GELLER: Sooo, Richard's shopping in the junior section.`,-1),c[217]||=a(`blockquote`,null,[a(`p`,null,`哦，理查德在初级区购物。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/051.mp3`}),c[218]||=i(),c[219]||=a(`strong`,null,`MONICA GELLER:`,-1),c[220]||=i(` Are we still on that?`,-1),c[221]||=a(`blockquote`,null,[a(`p`,null,`我们还在谈这个吗？`)],-1),c[222]||=a(`p`,null,`MRS. GELLER: We just know she's got the IQ of a napkin.`,-1),c[223]||=a(`blockquote`,null,[a(`p`,null,`我们只知道她有餐巾般的智商。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/052.mp3`}),c[224]||=i(),c[225]||=a(`strong`,null,`FRIEND:`,-1),c[226]||=i(` She's probably not even very pretty, just young enough so that everything is still pointing up. [Monica folds her arms over her breasts]`,-1),c[227]||=a(`blockquote`,null,[a(`p`,null,`她可能还不是很漂亮，只是还很年轻，所以一切都很好。[莫妮卡用双臂捂住胸部]`)],-1),c[228]||=a(`hr`,null,null,-1),c[229]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Joey's co-star's apartment. Chandler and Joey are at the brunch.`)],-1),c[230]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`乔伊的联袂主演的公寓。钱德勒和乔伊正在吃早午餐。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/053.mp3`}),c[231]||=i(),c[232]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[233]||=i(` Can you believe this place?`,-1),c[234]||=a(`blockquote`,null,[a(`p`,null,`你能相信这个地方吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/054.mp3`}),c[235]||=i(),c[236]||=a(`strong`,null,`CHANDLER BING:`,-1),c[237]||=i(` I know, this is a great apartment.`,-1),c[238]||=a(`blockquote`,null,[a(`p`,null,`我知道，这是一套很棒的公寓。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/055.mp3`}),c[239]||=i(),c[240]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[241]||=i(` Ah, I was just in the bathroom, and there's mirrors on both sides of you. So when you're in there it's like you're peein' with the Rockettes.`,-1),c[242]||=a(`blockquote`,null,[a(`p`,null,`啊，我刚才在浴室里，你的两边都有镜子。所以当你在里面的时候，就像你在和摇滚女郎一起撒尿。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/056.mp3`}),c[243]||=i(),c[244]||=a(`strong`,null,`CHANDLER BING:`,-1),c[245]||=i(` Wow, there's my fantasy come true. No, seriously.`,-1),c[246]||=a(`blockquote`,null,[a(`p`,null,`哇，我的幻想成真了。不，说真的。`)],-1),c[247]||=a(`p`,null,`JOEY'S CO-STAR: Hey.`,-1),c[248]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/057.mp3`}),c[249]||=i(),c[250]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[251]||=i(` Hey! We were just sayin', great apartment man.`,-1),c[252]||=a(`blockquote`,null,[a(`p`,null,`嘿！我们只是说，很棒的公寓男人。`)],-1),c[253]||=a(`p`,null,`JOEY'S CO-STAR: Thanks. You want it?`,-1),c[254]||=a(`blockquote`,null,[a(`p`,null,`谢谢。你想要吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/058.mp3`}),c[255]||=i(),c[256]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[257]||=i(` Huh?`,-1),c[258]||=a(`blockquote`,null,[a(`p`,null,`嗯？`)],-1),c[259]||=a(`p`,null,`JOEY'S CO-STAR: Yeah, I'm movin' to a bigger place. You should definitely take this one.`,-1),c[260]||=a(`blockquote`,null,[a(`p`,null,`是的，我要搬到一个更大的地方。你一定要买这个。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/059.mp3`}),c[261]||=i(),c[262]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[263]||=i(` Yeah, can you see me in a place like this?`,-1),c[264]||=a(`blockquote`,null,[a(`p`,null,`是啊，你能在这样的地方看到我吗？`)],-1),c[265]||=a(`p`,null,`JOEY'S CO-STAR: Why not? You hate park views and high ceilings? C'mon I'll show you the kitchen.`,-1),c[266]||=a(`blockquote`,null,[a(`p`,null,`为什么不呢？你讨厌公园的景色和高高的天花板？来吧，我带你去厨房。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/060.mp3`}),c[267]||=t(` <strong>CHANDLER BING:</strong> [being left behind] Oh that&#39;s all right fellas, I saw a kitchen this morning - on TV. Stop talking. OK.<blockquote><p>（落在后面）哦，没关系，伙计们，我今天早上在电视上看到一个厨房。别说了。好啊</p></blockquote><hr><p>🎬 <em>Mr. Geller&#39;s party. Mr. Geller and a friend are questioning Richard while Ross observes.</em></p><blockquote><p>🎬 <em>盖勒先生的聚会。盖勒先生和一个朋友在问理查德，而罗斯在观察。</em></p></blockquote><p>MR. GELLER: C&#39;mon, tell us.</p><blockquote><p>来吧，告诉我们。</p></blockquote>`,9),r(p,{src:`/audio/friends/S02/S02E16/061.mp3`}),c[268]||=i(),c[269]||=a(`strong`,null,`FRIEND:`,-1),c[270]||=i(` Yeah, is she really 20.`,-1),c[271]||=a(`blockquote`,null,[a(`p`,null,`是的，她真的20岁吗。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/062.mp3`}),c[272]||=i(),c[273]||=a(`strong`,null,`RICHARD:`,-1),c[274]||=i(` I am not telling you guys anything.`,-1),c[275]||=a(`blockquote`,null,[a(`p`,null,`我什么都没告诉你们。`)],-1),c[276]||=a(`p`,null,`MR. GELLER: C'mon Rich, it's my birthday, let me live vicariously.`,-1),c[277]||=a(`blockquote`,null,[a(`p`,null,`来吧，里奇，今天是我的生日，让我过一种替代的生活。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/063.mp3`}),c[278]||=i(),c[279]||=a(`strong`,null,`ROSS GELLER:`,-1),c[280]||=i(` Dad, you really don't want to do that.`,-1),c[281]||=a(`blockquote`,null,[a(`p`,null,`爸爸，你真的不想那样做。`)],-1),c[282]||=a(`p`,null,`MR. GELLER: Ahh, what's a little mid-life crisis between friends?`,-1),c[283]||=a(`blockquote`,null,[a(`p`,null,`啊，朋友之间的中年危机是什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/064.mp3`}),c[284]||=i(),c[285]||=a(`strong`,null,`RICHARD:`,-1),c[286]||=i(` Jack, would you let it go?`,-1),c[287]||=a(`blockquote`,null,[a(`p`,null,`杰克，你会放过它吗？`)],-1),c[288]||=a(`p`,null,`MR. GELLER: Look, I know what you're going through. When I turned 50 I got the Porsche. You... you got your own little speedster.`,-1),c[289]||=a(`blockquote`,null,[a(`p`,null,`听着，我知道你在经历什么。我50岁时买了保时捷。你。。。你有自己的小speedster。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/065.mp3`}),c[290]||=i(),c[291]||=a(`strong`,null,`RICHARD:`,-1),c[292]||=i(` Guys. Seriously, it is not like that.`,-1),c[293]||=a(`blockquote`,null,[a(`p`,null,`伙计们。说真的，不是这样的。`)],-1),c[294]||=a(`p`,null,`MR. GELLER: Tell you what, maybe one of these weekends you can borrow the car and I cou. . .`,-1),c[295]||=a(`blockquote`,null,[a(`p`,null,`告诉你吧，也许有一个周末你可以借我的车，我可以。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/066.mp3`}),c[296]||=t(` <strong>ROSS GELLER:</strong> Dad, I beg you not to finish that sentence.<blockquote><p>爸爸，我求你不要说完那句话。</p></blockquote><p>MR. GELLER: What? I&#39;m kidding. You know I&#39;d never let him touch the Porsche.</p><blockquote><p>什么？我在开玩笑。你知道我不会让他碰那辆保时捷的。</p></blockquote><hr><p>🎬 <em>Tattoo parlor. Phoebe and Rachel are deciding on tattoos.</em></p><blockquote><p>🎬 <em>纹身店。菲比和瑞秋决定纹身。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S02/S02E16/067.mp3`}),c[297]||=i(),c[298]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[299]||=i(` OK Rach, which, which lily? This lily or that lily?`,-1),c[300]||=a(`blockquote`,null,[a(`p`,null,`好吧，瑞秋，哪个，哪个莉莉？这个百合花还是那个百合花？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/068.mp3`}),c[301]||=i(),c[302]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[303]||=i(` Well I. . .`,-1),c[304]||=a(`blockquote`,null,[a(`p`,null,`我。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/069.mp3`}),c[305]||=i(),c[306]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[307]||=i(` I like this lily. It's more open, ya know, and that's like my mom. She had a more open, giving spirit. Ooh, Foghorn Leghorn, ooh.`,-1),c[308]||=a(`blockquote`,null,[a(`p`,null,`我喜欢这个莉莉。它更开放，你知道，就像我妈妈一样。她有一种更加开放、乐于助人的精神。哦，雾号，来航号，哦。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/070.mp3`}),c[309]||=i(),c[310]||=a(`strong`,null,`TATTOO ARTIST:`,-1),c[311]||=i(` Alright, blonde girl, you're in room two, not so blonde girl, you're with me.`,-1),c[312]||=a(`blockquote`,null,[a(`p`,null,`好吧，金发女郎，你在二号房间，不是金发女郎，你和我在一起。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/071.mp3`}),c[313]||=i(),c[314]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[315]||=i(` Here we go.`,-1),c[316]||=a(`blockquote`,null,[a(`p`,null,`开始了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/072.mp3`}),c[317]||=i(),c[318]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[319]||=i(` [reluctantly] Uh-huh.`,-1),c[320]||=a(`blockquote`,null,[a(`p`,null,`（不情愿地）嗯。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/073.mp3`}),c[321]||=i(),c[322]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[323]||=i(` You're not going?`,-1),c[324]||=a(`blockquote`,null,[a(`p`,null,`你不去了？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/074.mp3`}),c[325]||=i(),c[326]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[327]||=i(` Uh-huh.`,-1),c[328]||=a(`blockquote`,null,[a(`p`,null,`嗯。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/075.mp3`}),c[329]||=i(),c[330]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[331]||=i(` What? Is it - is this 'cause of what Ross said?`,-1),c[332]||=a(`blockquote`,null,[a(`p`,null,`什么？这是因为罗斯说的吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/076.mp3`}),c[333]||=i(),c[334]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[335]||=i(` No. Well, yeah, maybe.`,-1),c[336]||=a(`blockquote`,null,[a(`p`,null,`不。嗯，是的，也许吧。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/077.mp3`}),c[337]||=i(),c[338]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[339]||=i(` I don't believe this. Is this how this relationship's gonna work? Ross equals boss. I mean, c'mon what is this, 1922?`,-1),c[340]||=a(`blockquote`,null,[a(`p`,null,`我不相信。这就是这种关系的运作方式吗？罗斯等于老板。我是说，拜托，这是什么，1922年？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/078.mp3`}),c[341]||=i(),c[342]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[343]||=i(` What's 1922?`,-1),c[344]||=a(`blockquote`,null,[a(`p`,null,`什么是1922年？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/079.mp3`}),c[345]||=i(),c[346]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[347]||=i(` Just, you know, long time ago. Well, when men used to tell women what to do - a lot. And then there was suffrage, which is a good thing but is sounds horrible. Do you want to get this tattoo?`,-1),c[348]||=a(`blockquote`,null,[a(`p`,null,`只是，你知道，很久以前。嗯，以前男人总是告诉女人该做什么——很多。还有选举权，这是件好事，但听起来很可怕。你想纹身吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/080.mp3`}),c[349]||=i(),c[350]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[351]||=i(` Yes I do, it's just that Ross is. . .`,-1),c[352]||=a(`blockquote`,null,[a(`p`,null,`是的，我知道，只是罗斯。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/081.mp3`}),c[353]||=i(),c[354]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[355]||=i(` OK, hey, HEY. Is your boyfriend the boss of you?`,-1),c[356]||=a(`blockquote`,null,[a(`p`,null,`好的，嘿，嘿。你男朋友是你的老板吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/082.mp3`}),c[357]||=i(),c[358]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[359]||=i(` No.`,-1),c[360]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/083.mp3`}),c[361]||=i(),c[362]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[363]||=i(` OK, who is the boss of you?!!`,-1),c[364]||=a(`blockquote`,null,[a(`p`,null,`好吧，谁是你的老板？！！`)],-1),r(p,{src:`/audio/friends/S02/S02E16/084.mp3`}),c[365]||=i(),c[366]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[367]||=i(` You?`,-1),c[368]||=a(`blockquote`,null,[a(`p`,null,`你呢？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/085.mp3`}),c[369]||=i(),c[370]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[371]||=i(` No. You are the boss of you. Now you march your heinie in there and get that heart tattooed on your hip. GO!!`,-1),c[372]||=a(`blockquote`,null,[a(`p`,null,`不，你是你的老板。现在你把你的海尼带进去，把那颗心纹在你的屁股上。去吧！！`)],-1),c[373]||=a(`hr`,null,null,-1),c[374]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Mr. Geller's birthday party. Monica is in the bathroom and Richard comes in.`)],-1),c[375]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`盖勒先生的生日派对。莫妮卡在浴室，理查德进来。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/086.mp3`}),c[376]||=i(),c[377]||=a(`strong`,null,`RICHARD:`,-1),c[378]||=i(` How ya doin'?`,-1),c[379]||=a(`blockquote`,null,[a(`p`,null,`你好吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/087.mp3`}),c[380]||=i(),c[381]||=a(`strong`,null,`MONICA GELLER:`,-1),c[382]||=i(` I'm a twinkie.`,-1),c[383]||=a(`blockquote`,null,[a(`p`,null,`我是双胞胎。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/088.mp3`}),c[384]||=i(),c[385]||=a(`strong`,null,`RICHARD:`,-1),c[386]||=i(` Really? I'm a hero.`,-1),c[387]||=a(`blockquote`,null,[a(`p`,null,`真的吗？我是英雄。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/089.mp3`}),c[388]||=i(),c[389]||=a(`strong`,null,`MONICA GELLER:`,-1),c[390]||=i(` Oh, this is so hard.`,-1),c[391]||=a(`blockquote`,null,[a(`p`,null,`哦，这太难了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/090.mp3`}),c[392]||=i(),c[393]||=a(`strong`,null,`RICHARD:`,-1),c[394]||=i(` Yeah, I know. I hate it too. Look, maybe we should just tell them.`,-1),c[395]||=a(`blockquote`,null,[a(`p`,null,`是的，我知道。我也讨厌它。听着，也许我们应该告诉他们。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/091.mp3`}),c[396]||=i(),c[397]||=a(`strong`,null,`MONICA GELLER:`,-1),c[398]||=i(` Maybe we should just tell your parents first.`,-1),c[399]||=a(`blockquote`,null,[a(`p`,null,`也许我们应该先告诉你父母。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/092.mp3`}),c[400]||=i(),c[401]||=a(`strong`,null,`RICHARD:`,-1),c[402]||=i(` My parents are dead.`,-1),c[403]||=a(`blockquote`,null,[a(`p`,null,`我父母死了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/093.mp3`}),c[404]||=i(),c[405]||=a(`strong`,null,`MONICA GELLER:`,-1),c[406]||=i(` God, you are so lucky. I mean, I mean. . . you know what I mean.`,-1),c[407]||=a(`blockquote`,null,[a(`p`,null,`天啊，你真幸运。我是说，我是说。你知道我的意思。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/094.mp3`}),c[408]||=i(),c[409]||=a(`strong`,null,`RICHARD:`,-1),c[410]||=i(` I know, I know. Just hang in there, OK. OK, I'll go out first, alright.`,-1),c[411]||=a(`blockquote`,null,[a(`p`,null,`我知道，我知道。坚持住，好吗。好的，我先出去，好吗。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/095.mp3`}),c[412]||=i(),c[413]||=a(`strong`,null,`MONICA GELLER:`,-1),c[414]||=i(` Alright.`,-1),c[415]||=a(`blockquote`,null,[a(`p`,null,`好的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/096.mp3`}),c[416]||=t(` <strong>RICHARD:</strong> [walks out of the bathroom and runs into Mrs. Geller who is going to the bathroom] Judy, going to the bathroom, good for you.<blockquote><p>（走出浴室，撞到了正要去洗手间的盖勒夫人）：朱迪，去洗手间，对你有好处。</p></blockquote><p>MRS. GELLER: Thank you Richard, I appreciate the support.</p><blockquote><p>谢谢你，理查德，我感谢你的支持。</p></blockquote><p>[Monica jumps in the shower. Right after Mrs. Geller enters the bathroom, Mr. Geller peeks his head in.]</p><blockquote><p>[莫妮卡跳进浴室。盖勒夫人刚进浴室，盖勒先生就把头探了进去。]</p></blockquote><p>MR. GELLER: Honey. Honey, have you seen my Harmon Kilerbrew bat? Bob doesn&#39;t believe I have one.</p><blockquote><p>亲爱的。亲爱的，你看到我的哈蒙·基尔布雷球棒了吗？鲍勃不相信我有。</p></blockquote><p>MRS. GELLER: I have no idea. Did you know Richard has a twinkie in the city?</p><blockquote><p>我不知道。你知道Richard在城里有一个twinkie吗？</p></blockquote><p>MR. GELLER: I know. He&#39;s like a new man. It&#39;s like a scene from Cocoon.</p><blockquote><p>我知道。他像个新人。就像《茧》里的一幕。</p></blockquote><p>MRS. GELLER: I just never would have pictured Richard with a bimbo.</p><blockquote><p>我永远不会想象理查德和一个荡妇在一起。</p></blockquote><p>MR. GELLER: Apparently, he told Johnny Shapiro that she&#39;s quite a girl. In fact, he told Johnny that he thinks he&#39;s falling in love with her.</p><blockquote><p>显然，他告诉约翰尼·夏皮罗，她是个很好的女孩。事实上，他告诉约翰尼，他认为自己爱上了她。</p></blockquote><p>MRS. GELLER: Really.</p><blockquote><p>真的。</p></blockquote><p>MR. GELLER: I tell you, I&#39;ve never seen him this happy.</p><blockquote><p>我告诉你，我从来没见过他这么高兴。</p></blockquote><p>MRS. GELLER: So Jack, you ever think about trading me in for a younger model?</p><blockquote><p>杰克，你有没有想过用我换一个更年轻的模特？</p></blockquote><p>MR. GELLER: Of course not. With you it&#39;s like I&#39;ve got two 25-year-olds.</p><blockquote><p>当然不是。和你在一起就像我有两个25岁的孩子。</p></blockquote><p>MRS. GELLER: [they start kissing] Oh Jack stop.</p><blockquote><p>（他们开始接吻）噢，杰克，住手。</p></blockquote><p>MR. GELLER: C&#39;mon, it&#39;s my birthday.</p><blockquote><p>来吧，今天是我的生日。</p></blockquote><hr><p>🎬 <em>Chandler and Joey&#39;s apartment. Chandler and Joey are returning from their brunch.</em></p><blockquote><p>🎬 <em>钱德勒和乔伊的公寓。钱德勒和乔伊从早午餐回来。</em></p></blockquote>`,33),r(p,{src:`/audio/friends/S02/S02E16/097.mp3`}),c[417]||=i(),c[418]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[419]||=i(` Can we drop this? I am not interested in the guy's apartment.`,-1),c[420]||=a(`blockquote`,null,[a(`p`,null,`我们能放下这个吗？我对那家伙的公寓不感兴趣。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/098.mp3`}),c[421]||=i(),c[422]||=a(`strong`,null,`CHANDLER BING:`,-1),c[423]||=i(` Oh please, I saw the way you were checking out his mouldings. You want it.`,-1),c[424]||=a(`blockquote`,null,[a(`p`,null,`噢，拜托，我看到你检查他的模型的方式了。你想要它。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/099.mp3`}),c[425]||=i(),c[426]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[427]||=i(` Why would I want another apartment, huh? I've already got an apartment that I love.`,-1),c[428]||=a(`blockquote`,null,[a(`p`,null,`我为什么要另一套公寓，嗯？我已经有一套我喜欢的公寓了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/100.mp3`}),c[429]||=i(),c[430]||=a(`strong`,null,`CHANDLER BING:`,-1),c[431]||=i(` Well it wouldn't kill you to say it once in a while.`,-1),c[432]||=a(`blockquote`,null,[a(`p`,null,`你偶尔说一次也不会死的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/101.mp3`}),c[433]||=i(),c[434]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[435]||=i(` Alright, you want the truth? I'm thinkin' about it.`,-1),c[436]||=a(`blockquote`,null,[a(`p`,null,`好吧，你想知道真相吗？我正在考虑。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/102.mp3`}),c[437]||=i(),c[438]||=a(`strong`,null,`CHANDLER BING:`,-1),c[439]||=i(` What?`,-1),c[440]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/103.mp3`}),c[441]||=i(),c[442]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[443]||=i(` I'm sorry. I'm 28 years old, I've never lived alone, and I'm finally at a place where I've got enough money that I don't need a roommate anymore.`,-1),c[444]||=a(`blockquote`,null,[a(`p`,null,`对不起。我28岁了，我从来没有一个人住过，我终于到了一个有钱的地方，不再需要室友了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/104.mp3`}),c[445]||=i(),c[446]||=a(`strong`,null,`CHANDLER BING:`,-1),c[447]||=i(` Woah, woah, woah. I don't need a roommate either, OK? I can afford to live here by myself. Ya know, I may have to bring in somebody once a week to lick the silverware.`,-1),c[448]||=a(`blockquote`,null,[a(`p`,null,`哇，哇，哇。我也不需要室友，好吗？我一个人住得起这里。你知道，我可能每周得请一个人来舔银器。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/105.mp3`}),c[449]||=i(),c[450]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[451]||=i(` What're you gettin' so bent out of shape for, huh? It's not like we agreed to live together forever. We're not Bert and Ernie.`,-1),c[452]||=a(`blockquote`,null,[a(`p`,null,`你为什么这么弯曲变形，嗯？我们并不是同意永远住在一起。我们不是伯特和厄尼。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/106.mp3`}),c[453]||=i(),c[454]||=a(`strong`,null,`CHANDLER BING:`,-1),c[455]||=i(` Look, you know what? If this is the way you feel, then maybe you should take it.`,-1),c[456]||=a(`blockquote`,null,[a(`p`,null,`听着，你知道吗？如果这是你的感觉，那么也许你应该接受它。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/107.mp3`}),c[457]||=i(),c[458]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[459]||=i(` Well that's how I feel.`,-1),c[460]||=a(`blockquote`,null,[a(`p`,null,`这就是我的感觉。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/108.mp3`}),c[461]||=i(),c[462]||=a(`strong`,null,`CHANDLER BING:`,-1),c[463]||=i(` Well then maybe you should take it.`,-1),c[464]||=a(`blockquote`,null,[a(`p`,null,`那么也许你应该把它拿走。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/109.mp3`}),c[465]||=i(),c[466]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[467]||=i(` Well then maybe I will.`,-1),c[468]||=a(`blockquote`,null,[a(`p`,null,`那也许我会的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/110.mp3`}),c[469]||=i(),c[470]||=a(`strong`,null,`CHANDLER BING:`,-1),c[471]||=i(` Fine with me.`,-1),c[472]||=a(`blockquote`,null,[a(`p`,null,`我很好。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/111.mp3`}),c[473]||=t(` <strong>JOEY TRIBBIANI:</strong> Great. Then you&#39;ll be able to spend more quality time with your real friends, the spoons.<blockquote><p>太好了。这样你就可以和真正的朋友汤匙一起度过更多的美好时光。</p></blockquote><hr><p>🎬 <em>Mr. Geller&#39;s birthday party. Mr. and Mrs. Geller enter looking particularly refreshed. Monica follows looking rather pale.</em></p><blockquote><p>🎬 <em>盖勒先生的生日派对。盖勒先生和夫人进来时神采奕奕。莫妮卡紧随其后，脸色苍白。</em></p></blockquote><p>MR. GELLER: Who&#39;s drink can I freshen?</p><blockquote><p>我可以给谁的饮料提神？</p></blockquote><p>MRS. GELLER: Almost time for cake.</p><blockquote><p>快到吃蛋糕的时间了。</p></blockquote>`,11),r(p,{src:`/audio/friends/S02/S02E16/112.mp3`}),c[474]||=i(),c[475]||=a(`strong`,null,`ROSS GELLER:`,-1),c[476]||=i(` Mon, Mon, are you OK?`,-1),c[477]||=a(`blockquote`,null,[a(`p`,null,`妈妈，妈妈，你还好吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/113.mp3`}),c[478]||=i(),c[479]||=a(`strong`,null,`MONICA GELLER:`,-1),c[480]||=i(` You remember that video I found of mom and dad?`,-1),c[481]||=a(`blockquote`,null,[a(`p`,null,`你还记得我找到的爸爸妈妈的视频吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/114.mp3`}),c[482]||=i(),c[483]||=a(`strong`,null,`ROSS GELLER:`,-1),c[484]||=i(` Yeah.`,-1),c[485]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/115.mp3`}),c[486]||=i(),c[487]||=a(`strong`,null,`MONICA GELLER:`,-1),c[488]||=i(` Well, I just caught the live show.`,-1),c[489]||=a(`blockquote`,null,[a(`p`,null,`嗯，我刚看了现场直播。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/116.mp3`}),c[490]||=i(),c[491]||=a(`strong`,null,`ROSS GELLER:`,-1),c[492]||=i(` Eww.`,-1),c[493]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),c[494]||=a(`hr`,null,null,-1),c[495]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Mr. Geller's birthday party. Monica and Richard are alone in the kitchen.`)],-1),c[496]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`盖勒先生的生日派对。莫妮卡和理查德单独在厨房里。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/117.mp3`}),c[497]||=i(),c[498]||=a(`strong`,null,`MONICA GELLER:`,-1),c[499]||=i(` Hey there.`,-1),c[500]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/118.mp3`}),c[501]||=i(),c[502]||=a(`strong`,null,`RICHARD:`,-1),c[503]||=i(` What?`,-1),c[504]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/119.mp3`}),c[505]||=i(),c[506]||=a(`strong`,null,`MONICA GELLER:`,-1),c[507]||=i(` Nothing, I just heard something nice about you.`,-1),c[508]||=a(`blockquote`,null,[a(`p`,null,`没什么，我只是听到一些关于你的好消息。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/120.mp3`}),c[509]||=i(),c[510]||=a(`strong`,null,`RICHARD:`,-1),c[511]||=i(` Humm, really?`,-1),c[512]||=a(`blockquote`,null,[a(`p`,null,`嗯，真的吗？`)],-1),c[513]||=a(`p`,null,`[Mrs. Geller and Ross both enter]`,-1),c[514]||=a(`blockquote`,null,[a(`p`,null,`[盖勒太太和罗斯都进来了]`)],-1),c[515]||=a(`p`,null,`MRS. GELLER: Richard. Richard. Your son isn't seeing anyone is he?`,-1),c[516]||=a(`blockquote`,null,[a(`p`,null,`理查德。理查德。你儿子没有和任何人约会，是吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/121.mp3`}),c[517]||=i(),c[518]||=a(`strong`,null,`RICHARD:`,-1),c[519]||=i(` Uhh, not that I know of.`,-1),c[520]||=a(`blockquote`,null,[a(`p`,null,`嗯，据我所知不是这样。`)],-1),c[521]||=a(`p`,null,`MRS. GELLER: Well, I was thinking, why doesn't he give Monica a call?`,-1),c[522]||=a(`blockquote`,null,[a(`p`,null,`嗯，我在想，他为什么不给莫妮卡打个电话？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/122.mp3`}),c[523]||=i(),c[524]||=a(`strong`,null,`RICHARD:`,-1),c[525]||=i(` That - that's an idea.`,-1),c[526]||=a(`blockquote`,null,[a(`p`,null,`那是个主意。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/123.mp3`}),c[527]||=i(),c[528]||=a(`strong`,null,`MONICA GELLER:`,-1),c[529]||=i(` Well, actually, I'm already seeing someone.`,-1),c[530]||=a(`blockquote`,null,[a(`p`,null,`嗯，事实上，我已经有约会了。`)],-1),c[531]||=a(`p`,null,`MRS. GELLER: Oh?`,-1),c[532]||=a(`blockquote`,null,[a(`p`,null,`哦？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/124.mp3`}),c[533]||=i(),c[534]||=a(`strong`,null,`RICHARD:`,-1),c[535]||=i(` Oh?`,-1),c[536]||=a(`blockquote`,null,[a(`p`,null,`哦？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/125.mp3`}),c[537]||=i(),c[538]||=a(`strong`,null,`ROSS GELLER:`,-1),c[539]||=i(` Ohh.`,-1),c[540]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),c[541]||=a(`p`,null,`MRS. GELLER: She never tells us anything. Ross, did you know Monica's seeing someone?`,-1),c[542]||=a(`blockquote`,null,[a(`p`,null,`她什么都没告诉我们。罗斯，你知道莫妮卡在约会吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/126.mp3`}),c[543]||=i(),c[544]||=a(`strong`,null,`ROSS GELLER:`,-1),c[545]||=i(` Mom, there are so many people in my life. Some of them are seeing people and some of them aren't. Is that crystal?`,-1),c[546]||=a(`blockquote`,null,[a(`p`,null,`妈妈，我的生活中有很多人。他们中的一些人在看人，而另一些人没有。那是水晶吗？`)],-1),c[547]||=a(`p`,null,`MRS. GELLER: So, who's the mystery man?`,-1),c[548]||=a(`blockquote`,null,[a(`p`,null,`那么，神秘人是谁？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/127.mp3`}),c[549]||=i(),c[550]||=a(`strong`,null,`MONICA GELLER:`,-1),c[551]||=i(` Well, uh, he's a doctor.`,-1),c[552]||=a(`blockquote`,null,[a(`p`,null,`嗯，他是个医生。`)],-1),c[553]||=a(`p`,null,`MRS. GELLER: A real doctor?`,-1),c[554]||=a(`blockquote`,null,[a(`p`,null,`一个真正的医生？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/128.mp3`}),c[555]||=i(),c[556]||=a(`strong`,null,`MONICA GELLER:`,-1),c[557]||=i(` No, a doctor of meat. Of course he's a real doctor. And he's handsome, and he's sweet, and know you'd like him. [she puts her arm around Richard]`,-1),c[558]||=a(`blockquote`,null,[a(`p`,null,`不，是个肉医生。他当然是个真正的医生。他很帅，很可爱，知道你会喜欢他的。[她搂住理查德]`)],-1),c[559]||=a(`p`,null,`MRS. GELLER: Well that's wonderful. . . I`,-1),c[560]||=a(`blockquote`,null,[a(`p`,null,`那太好了。我`)],-1),r(p,{src:`/audio/friends/S02/S02E16/129.mp3`}),c[561]||=i(),c[562]||=a(`strong`,null,`MONICA GELLER:`,-1),c[563]||=i(` Mom, it's OK.`,-1),c[564]||=a(`blockquote`,null,[a(`p`,null,`妈妈，没关系。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/130.mp3`}),c[565]||=i(),c[566]||=a(`strong`,null,`RICHARD:`,-1),c[567]||=i(` It is Judy.`,-1),c[568]||=a(`blockquote`,null,[a(`p`,null,`是朱迪。`)],-1),c[569]||=a(`p`,null,`MRS. GELLER: Jack. Could you come in here for a moment? NOW!`,-1),c[570]||=a(`blockquote`,null,[a(`p`,null,`杰克。你能进来一会儿吗？现在！`)],-1),c[571]||=a(`p`,null,`MR. GELLER: [enters with his bat] Found it.`,-1),c[572]||=a(`blockquote`,null,[a(`p`,null,`（拿着球棒进来）找到了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/131.mp3`}),c[573]||=i(),c[574]||=a(`strong`,null,`ROSS GELLER:`,-1),c[575]||=i(` I'll take that dad. [grabs the bat]`,-1),c[576]||=a(`blockquote`,null,[a(`p`,null,`我要那个爸爸。[抓住球棒]`)],-1),c[577]||=a(`p`,null,`MRS. GELLER: It seems your daughter and Richard are something of an item.`,-1),c[578]||=a(`blockquote`,null,[a(`p`,null,`看来你女儿和理查德是一对。`)],-1),c[579]||=a(`p`,null,`MR. GELLER: That's impossible, he's got a twinkie in the city.`,-1),c[580]||=a(`blockquote`,null,[a(`p`,null,`那是不可能的，他在城里有一个小面包。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/132.mp3`}),c[581]||=i(),c[582]||=a(`strong`,null,`MONICA GELLER:`,-1),c[583]||=i(` Dad, I'm the twinkie.`,-1),c[584]||=a(`blockquote`,null,[a(`p`,null,`爸爸，我是双胞胎。`)],-1),c[585]||=a(`p`,null,`MR. GELLER: You're the twinkie?`,-1),c[586]||=a(`blockquote`,null,[a(`p`,null,`你是双胞胎？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/133.mp3`}),c[587]||=i(),c[588]||=a(`strong`,null,`RICHARD:`,-1),c[589]||=i(` She's not a twinkie.`,-1),c[590]||=a(`blockquote`,null,[a(`p`,null,`她不是双胞胎。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/134.mp3`}),c[591]||=i(),c[592]||=a(`strong`,null,`MONICA GELLER:`,-1),c[593]||=i(` Al-alright, l-look you guys, this is the best relationship I've been in. . .`,-1),c[594]||=a(`blockquote`,null,[a(`p`,null,`好吧，我看你们，这是我经历过的最好的一段感情。`)],-1),c[595]||=a(`p`,null,`MRS. GELLER: Oh please, a relationship.`,-1),c[596]||=a(`blockquote`,null,[a(`p`,null,`噢，拜托，一段感情。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/135.mp3`}),c[597]||=i(),c[598]||=a(`strong`,null,`MONICA GELLER:`,-1),c[599]||=i(` Yes, a relationship. For your information I am crazy about this man.`,-1),c[600]||=a(`blockquote`,null,[a(`p`,null,`是的，一段感情。告诉你，我对这个男人很着迷。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/136.mp3`}),c[601]||=i(),c[602]||=a(`strong`,null,`RICHARD:`,-1),c[603]||=i(` Really?`,-1),c[604]||=a(`blockquote`,null,[a(`p`,null,`真的吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/137.mp3`}),c[605]||=i(),c[606]||=a(`strong`,null,`MONICA GELLER:`,-1),c[607]||=i(` Yes.`,-1),c[608]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),c[609]||=a(`p`,null,`MR. GELLER: Am I supposed to stand here and listen to this on my birthday?`,-1),c[610]||=a(`blockquote`,null,[a(`p`,null,`我应该在生日那天站在这里听这个吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/138.mp3`}),c[611]||=i(),c[612]||=a(`strong`,null,`MONICA GELLER:`,-1),c[613]||=i(` Dad, dad this is a good thing for me. Ya know, and you even said yourself, you've never seen Richard happier.`,-1),c[614]||=a(`blockquote`,null,[a(`p`,null,`爸爸，爸爸，这对我来说是件好事。你知道吗，你自己也说过，你从未见过理查德更快乐。`)],-1),c[615]||=a(`p`,null,`MR. GELLER: When did I say that?`,-1),c[616]||=a(`blockquote`,null,[a(`p`,null,`我什么时候说的？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/139.mp3`}),c[617]||=t(` <strong>MONICA GELLER:</strong> Upstairs in the bathroom right before you felt up mom.<blockquote><p>就在你起床之前，在楼上的浴室里，妈妈。</p></blockquote><p>[Everyone else enters and all start singing Happy Birthday.]</p><blockquote><p>[其他人都进来了，开始唱生日快乐歌。]</p></blockquote><hr><p>🎬 <em>Tattoo parlor. Rachel is showing Phoebe her tattoo.</em></p><blockquote><p>🎬 <em>纹身店。瑞秋正在给菲比看她的纹身。</em></p></blockquote>`,9),r(p,{src:`/audio/friends/S02/S02E16/140.mp3`}),c[618]||=i(),c[619]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[620]||=i(` Oh that looks so good, oh I love it.`,-1),c[621]||=a(`blockquote`,null,[a(`p`,null,`哦，看起来真不错，哦，我喜欢。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/141.mp3`}),c[622]||=i(),c[623]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[624]||=i(` I know, so do I. Oh Phoebe, I'm so glad you made me do this. OK, lemme se yours.`,-1),c[625]||=a(`blockquote`,null,[a(`p`,null,`我知道，我也是。哦，菲比，我很高兴你让我这么做。好的，让我看看你的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/142.mp3`}),c[626]||=i(),c[627]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[628]||=i(` Ahh. OK, let's see yours again.`,-1),c[629]||=a(`blockquote`,null,[a(`p`,null,`啊。好的，让我们再看看你的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/143.mp3`}),c[630]||=i(),c[631]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[632]||=i(` Phoebe we just saw mine, let me see yours.`,-1),c[633]||=a(`blockquote`,null,[a(`p`,null,`菲比，我们刚看到我的，让我看看你的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/144.mp3`}),c[634]||=i(),c[635]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[636]||=i(` Oh OK. [pulls over her shirt and shows a bare shoulder] Oh no, oh it's gone, that's so weird, I don't know how-where it went.`,-1),c[637]||=a(`blockquote`,null,[a(`p`,null,`哦，好的。[拉过她的衬衫，露出赤裸的肩膀]哦，不，哦，它不见了，太奇怪了，我不知道它怎么去了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/145.mp3`}),c[638]||=i(),c[639]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[640]||=i(` You didn't get it?`,-1),c[641]||=a(`blockquote`,null,[a(`p`,null,`你不明白吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/146.mp3`}),c[642]||=i(),c[643]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[644]||=i(` No.`,-1),c[645]||=a(`blockquote`,null,[a(`p`,null,`没有。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/147.mp3`}),c[646]||=i(),c[647]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[648]||=i(` Why didn't you get it?`,-1),c[649]||=a(`blockquote`,null,[a(`p`,null,`你为什么不明白？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/148.mp3`}),c[650]||=i(),c[651]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[652]||=i(` I'm sorry, I'm sorry.`,-1),c[653]||=a(`blockquote`,null,[a(`p`,null,`对不起，对不起。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/149.mp3`}),c[654]||=i(),c[655]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[656]||=i(` Phoebe, how would you do this to me? This was all your idea.`,-1),c[657]||=a(`blockquote`,null,[a(`p`,null,`菲比，你怎么会这样对我？这都是你的主意。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/150.mp3`}),c[658]||=i(),c[659]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[660]||=i(` I know, I know, and I was gonna get it but then he came in with this needle and uh, di-, did you know they do this with needles?`,-1),c[661]||=a(`blockquote`,null,[a(`p`,null,`我知道，我知道，我本来想去拿的，但后来他拿着这根针进来了，呃，迪-，你知道他们是用针做的吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/151.mp3`}),c[662]||=i(),c[663]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[664]||=i(` Really? You don't say, because mine was licked on by kittens.`,-1),c[665]||=a(`blockquote`,null,[a(`p`,null,`真的吗？你不会说，因为我的被小猫舔了。`)],-1),c[666]||=a(`hr`,null,null,-1),c[667]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler and Joey's apartment. Chandler is at the bar and Joey enters.`)],-1),c[668]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒和乔伊的公寓。钱德勒在酒吧，乔伊进来。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/152.mp3`}),c[669]||=i(),c[670]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[671]||=i(` Hey.`,-1),c[672]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/153.mp3`}),c[673]||=i(),c[674]||=a(`strong`,null,`CHANDLER BING:`,-1),c[675]||=i(` Hey.`,-1),c[676]||=a(`blockquote`,null,[a(`p`,null,`嘿。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/154.mp3`}),c[677]||=i(),c[678]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[679]||=i(` Hey listen, I'm sorry about what happened. . .`,-1),c[680]||=a(`blockquote`,null,[a(`p`,null,`嘿，听着，我对发生的事感到抱歉。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/155.mp3`}),c[681]||=i(),c[682]||=a(`strong`,null,`CHANDLER BING:`,-1),c[683]||=i(` Yeah me too.`,-1),c[684]||=a(`blockquote`,null,[a(`p`,null,`是的，我也是。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/156.mp3`}),c[685]||=i(),c[686]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[687]||=i(` I know. Yeah.`,-1),c[688]||=a(`blockquote`,null,[a(`p`,null,`我知道。是 啊`)],-1),r(p,{src:`/audio/friends/S02/S02E16/157.mp3`}),c[689]||=i(),c[690]||=a(`strong`,null,`CHANDLER BING:`,-1),c[691]||=i(` Yeah. So do we need to hug here or. . .`,-1),c[692]||=a(`blockquote`,null,[a(`p`,null,`是的。我们需要在这里拥抱还是。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/158.mp3`}),c[693]||=i(),c[694]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[695]||=i(` No, we're alright.`,-1),c[696]||=a(`blockquote`,null,[a(`p`,null,`不，我们没事。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/159.mp3`}),c[697]||=i(),c[698]||=a(`strong`,null,`CHANDLER BING:`,-1),c[699]||=i(` So I got ya something. [tosses Joey a bag of plastic spoons]`,-1),c[700]||=a(`blockquote`,null,[a(`p`,null,`所以我给你买了些东西。[向乔伊扔了一袋塑料汤匙]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/160.mp3`}),c[701]||=i(),c[702]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[703]||=i(` Plastic spoons. Great.`,-1),c[704]||=a(`blockquote`,null,[a(`p`,null,`塑料勺子。伟大的`)],-1),r(p,{src:`/audio/friends/S02/S02E16/161.mp3`}),c[705]||=i(),c[706]||=a(`strong`,null,`CHANDLER BING:`,-1),c[707]||=i(` Lick away my man.`,-1),c[708]||=a(`blockquote`,null,[a(`p`,null,`舔掉我的男人。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/162.mp3`}),c[709]||=i(),c[710]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[711]||=i(` These'll go great in my new place. You know, 'till I get real ones.`,-1),c[712]||=a(`blockquote`,null,[a(`p`,null,`这些在我的新家会很好。你知道，直到我得到真正的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/163.mp3`}),c[713]||=i(),c[714]||=a(`strong`,null,`CHANDLER BING:`,-1),c[715]||=i(` What?`,-1),c[716]||=a(`blockquote`,null,[a(`p`,null,`什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/164.mp3`}),c[717]||=i(),c[718]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[719]||=i(` Well, I can't use these forever. I mean, let's face it, they're no friend to the environment.`,-1),c[720]||=a(`blockquote`,null,[a(`p`,null,`嗯，我不能永远用这些。我的意思是，让我们面对现实，他们对环境不是朋友。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/165.mp3`}),c[721]||=i(),c[722]||=a(`strong`,null,`CHANDLER BING:`,-1),c[723]||=i(` No-no, I mean what, what's this about your new place?`,-1),c[724]||=a(`blockquote`,null,[a(`p`,null,`不，不，我是说，你的新家怎么了？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/166.mp3`}),c[725]||=i(),c[726]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[727]||=i(` I'm movin' out like we talked about.`,-1),c[728]||=a(`blockquote`,null,[a(`p`,null,`我要走了，就像我们说的那样。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/167.mp3`}),c[729]||=i(),c[730]||=a(`strong`,null,`CHANDLER BING:`,-1),c[731]||=i(` Well I didn't think that was serious. [grabs the spoons back] Ya know I thought that was just a fight.`,-1),c[732]||=a(`blockquote`,null,[a(`p`,null,`我不认为那是认真的。你知道我以为那只是一场搏斗。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/168.mp3`}),c[733]||=i(),c[734]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[735]||=i(` Well, it was a fight. . . based on serious stuff, remember. About how I never lived alone or anything. I just think it would be good for me, ya know, help me to grow or. . . whatever.`,-1),c[736]||=a(`blockquote`,null,[a(`p`,null,`嗯，那是一场搏斗。基于严肃的事情，记住。我从来没有独自生活过。我只是觉得这对我有好处，你知道，帮助我成长或者。无论什么`)],-1),r(p,{src:`/audio/friends/S02/S02E16/169.mp3`}),c[737]||=i(),c[738]||=a(`strong`,null,`CHANDLER BING:`,-1),c[739]||=i(` Well, there you go.`,-1),c[740]||=a(`blockquote`,null,[a(`p`,null,`好吧，给你。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/170.mp3`}),c[741]||=i(),c[742]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[743]||=i(` Hey, are you cool with this. I mean, I don't want to leave you high and dry.`,-1),c[744]||=a(`blockquote`,null,[a(`p`,null,`嘿，你对这个没意见吧。我是说，我不想让你孤立无援。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/171.mp3`}),c[745]||=i(),c[746]||=a(`strong`,null,`CHANDLER BING:`,-1),c[747]||=i(` Hey, no, I've never been lower or wetter. I'll be fine. I'll just turn your, uh, bedroom into a game room or somethin', you know, put the foosball table in there.`,-1),c[748]||=a(`blockquote`,null,[a(`p`,null,`嘿，不，我从来没有这么低或这么湿过。我会没事的。我会把你的卧室变成游戏室之类的，你知道，把足球桌放进去。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/172.mp3`}),c[749]||=i(),c[750]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[751]||=i(` Woah. Why do you get to keep the table?`,-1),c[752]||=a(`blockquote`,null,[a(`p`,null,`哇。你为什么要保留这张桌子？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/173.mp3`}),c[753]||=i(),c[754]||=a(`strong`,null,`CHANDLER BING:`,-1),c[755]||=i(` I did pay for half of it.`,-1),c[756]||=a(`blockquote`,null,[a(`p`,null,`我确实付了一半。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/174.mp3`}),c[757]||=i(),c[758]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[759]||=i(` Yeah. And uh, I paid for the other half.`,-1),c[760]||=a(`blockquote`,null,[a(`p`,null,`是的。我付了另一半的钱。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/175.mp3`}),c[761]||=i(),c[762]||=a(`strong`,null,`CHANDLER BING:`,-1),c[763]||=i(` Alright I'll tell you what, I'll play you for it.`,-1),c[764]||=a(`blockquote`,null,[a(`p`,null,`好吧，我告诉你吧，我会让你玩的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/176.mp3`}),c[765]||=i(),c[766]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[767]||=i(` Alright, you're on. I can take two minutes out of my day to kick your ass.`,-1),c[768]||=a(`blockquote`,null,[a(`p`,null,`好吧，你上场了。我可以抽出两分钟来揍你。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/177.mp3`}),c[769]||=i(),c[770]||=a(`strong`,null,`CHANDLER BING:`,-1),c[771]||=i(` Your little men are gonna get scored on more times than your sister.`,-1),c[772]||=a(`blockquote`,null,[a(`p`,null,`你的小个子男人会比你妹妹得分更多。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/178.mp3`}),c[773]||=i(),c[774]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[775]||=i(` Woah, woah, woah, woah. Which sister?`,-1),c[776]||=a(`blockquote`,null,[a(`p`,null,`哇，哇，哇，哇，哇。哪个姐姐？`)],-1),c[777]||=a(`hr`,null,null,-1),c[778]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Monica and Rachel's apartment. Monica and Richard are setting the table.`)],-1),c[779]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`莫妮卡和瑞秋的公寓。莫妮卡和理查德正在摆桌子。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/179.mp3`}),c[780]||=i(),c[781]||=a(`strong`,null,`MONICA GELLER:`,-1),c[782]||=i(` So, are you sorry that I told them?`,-1),c[783]||=a(`blockquote`,null,[a(`p`,null,`那么，我告诉他们你很抱歉吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/180.mp3`}),c[784]||=i(),c[785]||=a(`strong`,null,`RICHARD:`,-1),c[786]||=i(` No, it's been a long time since your dad and I went running.`,-1),c[787]||=a(`blockquote`,null,[a(`p`,null,`不，你爸爸和我很久没有跑步了。`)],-1),c[788]||=a(`p`,null,`[Rachel and Phoebe enter]`,-1),c[789]||=a(`blockquote`,null,[a(`p`,null,`[瑞秋和菲比进来]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/181.mp3`}),c[790]||=i(),c[791]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[792]||=i(` Oh.`,-1),c[793]||=a(`blockquote`,null,[a(`p`,null,`哦。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/182.mp3`}),c[794]||=i(),c[795]||=a(`strong`,null,`MONICA GELLER:`,-1),c[796]||=i(` Oh. Well did you get it? Let me see.`,-1),c[797]||=a(`blockquote`,null,[a(`p`,null,`哦。你明白了吗？我想一下。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/183.mp3`}),c[798]||=i(),c[799]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[800]||=i(` Is Ross here?`,-1),c[801]||=a(`blockquote`,null,[a(`p`,null,`罗斯在吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/184.mp3`}),c[802]||=i(),c[803]||=a(`strong`,null,`MONICA GELLER:`,-1),c[804]||=i(` No he went out to get pizza.`,-1),c[805]||=a(`blockquote`,null,[a(`p`,null,`不，他出去吃比萨饼了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/185.mp3`}),c[806]||=i(),c[807]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[808]||=i(` Oh really, OK. [shows Monica her tattoo]`,-1),c[809]||=a(`blockquote`,null,[a(`p`,null,`哦，真的，好的。[给莫妮卡看她的纹身]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/186.mp3`}),c[810]||=i(),c[811]||=a(`strong`,null,`MONICA GELLER:`,-1),c[812]||=i(` That's great.`,-1),c[813]||=a(`blockquote`,null,[a(`p`,null,`太好了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/187.mp3`}),c[814]||=i(),c[815]||=a(`strong`,null,`RICHARD:`,-1),c[816]||=i(` Very tasteful.`,-1),c[817]||=a(`blockquote`,null,[a(`p`,null,`很有品味。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/188.mp3`}),c[818]||=i(),c[819]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[820]||=i(` Wanna see mine, wanna see mine?`,-1),c[821]||=a(`blockquote`,null,[a(`p`,null,`想看看我的，想看看我的吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/189.mp3`}),c[822]||=i(),c[823]||=a(`strong`,null,`MONICA GELLER:`,-1),c[824]||=i(` Yes.`,-1),c[825]||=a(`blockquote`,null,[a(`p`,null,`是的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/190.mp3`}),c[826]||=i(),c[827]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[828]||=i(` What? You didn't get one.`,-1),c[829]||=a(`blockquote`,null,[a(`p`,null,`什么？你没有得到一个。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/191.mp3`}),c[830]||=i(),c[831]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[832]||=i(` OK, well then what is this? [shows her bare shoulder]`,-1),c[833]||=a(`blockquote`,null,[a(`p`,null,`好吧，那这是什么？[露出裸露的肩膀]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/192.mp3`}),c[834]||=i(),c[835]||=a(`strong`,null,`RICHARD:`,-1),c[836]||=i(` What're we looking at? That blue freckle?`,-1),c[837]||=a(`blockquote`,null,[a(`p`,null,`我们在看什么？那个蓝色的雀斑？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/193.mp3`}),c[838]||=i(),c[839]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[840]||=i(` OK, that's my tattoo.`,-1),c[841]||=a(`blockquote`,null,[a(`p`,null,`好的，那是我的纹身。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/194.mp3`}),c[842]||=i(),c[843]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[844]||=i(` That is not a tattoo, that is a nothing. I finally got her back in the chair, bairly touched her with a needle, she jumped up screaming, and that was it.`,-1),c[845]||=a(`blockquote`,null,[a(`p`,null,`那不是纹身，那什么都不是。我终于让她回到椅子上，贝利用针碰了碰她，她尖叫着跳了起来，就这样。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/195.mp3`}),c[846]||=i(),c[847]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[848]||=i(` OK, hi. For your information this is exactly what I wanted. This is a tattoo of the earth as seen from a great distance. It's the way my mother sees me from heaven.`,-1),c[849]||=a(`blockquote`,null,[a(`p`,null,`好的，嗨。供你参考，这正是我想要的。从远处看，这是一个地球纹身。这是我妈妈从天堂看到我的方式。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/196.mp3`}),c[850]||=i(),c[851]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[852]||=i(` Oh, what a load of crap. That is a dot. Your mother is up in heaven going, 'Where the hell is my lily, you wuss?' OK, Phoebe, that is not a tattoo, this is a tattoo. [she bends over and bears her tattoo right when Ross returns]`,-1),c[853]||=a(`blockquote`,null,[a(`p`,null,`哦，真是一堆废话。那是一个点。你妈妈在天堂说，“我的莉莉到底在哪里，你这个胆小鬼？”好吧，菲比，那不是纹身，这是纹身。[罗斯回来时，她弯下腰，纹身]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/197.mp3`}),c[854]||=i(),c[855]||=a(`strong`,null,`ROSS GELLER:`,-1),c[856]||=i(` You got a tattoo?`,-1),c[857]||=a(`blockquote`,null,[a(`p`,null,`你有纹身吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/198.mp3`}),c[858]||=i(),c[859]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[860]||=i(` Maybe. But just a little one. Phoebe got the whole world.`,-1),c[861]||=a(`blockquote`,null,[a(`p`,null,`也许吧。但只是一个小的。菲比得到了整个世界。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/199.mp3`}),c[862]||=i(),c[863]||=a(`strong`,null,`ROSS GELLER:`,-1),c[864]||=i(` Lemme see. [looks]`,-1),c[865]||=a(`blockquote`,null,[a(`p`,null,`让我看看。[表情]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/200.mp3`}),c[866]||=i(),c[867]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[868]||=i(` Well?`,-1),c[869]||=a(`blockquote`,null,[a(`p`,null,`嗯？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/201.mp3`}),c[870]||=i(),c[871]||=a(`strong`,null,`ROSS GELLER:`,-1),c[872]||=i(` Well it's really. . . sexy. I wouldn't have thought it would be but. . . wow.`,-1),c[873]||=a(`blockquote`,null,[a(`p`,null,`嗯，真的。性感的我没想到会这样，但是。哇！`)],-1),r(p,{src:`/audio/friends/S02/S02E16/202.mp3`}),c[874]||=i(),c[875]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[876]||=i(` Really?`,-1),c[877]||=a(`blockquote`,null,[a(`p`,null,`真的吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/203.mp3`}),c[878]||=i(),c[879]||=a(`strong`,null,`ROSS GELLER:`,-1),c[880]||=i(` Yeah, so uh, is it sore or can you do stuff?`,-1),c[881]||=a(`blockquote`,null,[a(`p`,null,`是的，那么，呃，是疼痛还是你能做些什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/204.mp3`}),c[882]||=i(),c[883]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[884]||=i(` I guess.`,-1),c[885]||=a(`blockquote`,null,[a(`p`,null,`我想是吧。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/205.mp3`}),c[886]||=i(),c[887]||=a(`strong`,null,`ROSS GELLER:`,-1),c[888]||=i(` Hey, save us some pizza. [they go off to Rachel's room]`,-1),c[889]||=a(`blockquote`,null,[a(`p`,null,`嘿，给我们留点比萨饼吧。[他们去了瑞秋的房间]`)],-1),c[890]||=a(`hr`,null,null,-1),c[891]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler's apartment. Chandler and Joey are playing foosball for the table.`)],-1),c[892]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒的公寓。钱德勒和乔伊正在桌上玩足球。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/206.mp3`}),c[893]||=i(),c[894]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[895]||=i(` Get out of the corner. Pass it, pass it.`,-1),c[896]||=a(`blockquote`,null,[a(`p`,null,`从角落里出来。传过来，传过来。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/207.mp3`}),c[897]||=i(),c[898]||=a(`strong`,null,`CHANDLER BING:`,-1),c[899]||=i(` Stop talkin' to your men. [Joey scores]`,-1),c[900]||=a(`blockquote`,null,[a(`p`,null,`别跟你的人说话了。[乔伊得分]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/208.mp3`}),c[901]||=i(),c[902]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[903]||=i(` Yes! And the table is mine.`,-1),c[904]||=a(`blockquote`,null,[a(`p`,null,`是的！桌子是我的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/209.mp3`}),c[905]||=i(),c[906]||=a(`strong`,null,`CHANDLER BING:`,-1),c[907]||=i(` Congratulations. [Chandler leaves]`,-1),c[908]||=a(`blockquote`,null,[a(`p`,null,`恭喜你。[钱德勒离开]`)],-1),c[909]||=a(`hr`,null,null,-1),c[910]||=a(`p`,null,[i(`🎬 `),a(`em`,null,`Chandler's apartment. The whole gang is helping Joey pack.`)],-1),c[911]||=a(`blockquote`,null,[a(`p`,null,[i(`🎬 `),a(`em`,null,`钱德勒的公寓。整个帮派都在帮乔伊收拾行李。`)])],-1),r(p,{src:`/audio/friends/S02/S02E16/210.mp3`}),c[912]||=i(),c[913]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[914]||=i(` Hey, you guys are still gonna come visit me, right?`,-1),c[915]||=a(`blockquote`,null,[a(`p`,null,`嘿，你们还是会来看我的，对吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/211.mp3`}),c[916]||=i(),c[917]||=a(`strong`,null,`CHANDLER BING:`,-1),c[918]||=i(` Oh yeah, you got the big TV. We'll be over there all the time. . . [Chandler gives him a look] except when we are here.`,-1),c[919]||=a(`blockquote`,null,[a(`p`,null,`哦，是的，你有大电视。我们会一直在那里。[钱德勒看了他一眼]除非我们在这里。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/212.mp3`}),c[920]||=i(),c[921]||=a(`strong`,null,`Phoebe Buffay:`,-1),c[922]||=i(` I know you're just moving uptown but I'm really gonna miss you.`,-1),c[923]||=a(`blockquote`,null,[a(`p`,null,`我知道你刚搬到住宅区，但我真的会想你的。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/213.mp3`}),c[924]||=i(),c[925]||=a(`strong`,null,`MONICA GELLER:`,-1),c[926]||=i(` I know, how can you not be accross the hall anymore.`,-1),c[927]||=a(`blockquote`,null,[a(`p`,null,`我知道，你怎么可能再也不能穿过大厅了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/214.mp3`}),c[928]||=i(),c[929]||=a(`strong`,null,`RACHEL GREEN:`,-1),c[930]||=i(` Yeah, who's gonna eat all our food, and tie up our phone lines, and - is that my bra? What the hell you doin' with my bra?`,-1),c[931]||=a(`blockquote`,null,[a(`p`,null,`是啊，谁会吃掉我们所有的食物，绑上我们的电话线，那是我的胸罩吗？你他妈的拿我的胸罩干什么？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/215.mp3`}),c[932]||=i(),c[933]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[934]||=i(` Oh no-no, it's uh, it's not what you think. We uh, we used it to, you know, fling water balloons off the roof. Remember that, those junior high kids couldn't even get theirs accross the street.`,-1),c[935]||=a(`blockquote`,null,[a(`p`,null,`哦，不，不，不是你想的那样。我们用它把水气球从屋顶上扔下来。记住，那些初中生甚至不能在街上玩。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/216.mp3`}),c[936]||=i(),c[937]||=a(`strong`,null,`CHANDLER BING:`,-1),c[938]||=i(` [quietly] Yeah, I remember.`,-1),c[939]||=a(`blockquote`,null,[a(`p`,null,`（平静地）是的，我记得。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/217.mp3`}),c[940]||=i(),c[941]||=a(`strong`,null,`ROSS GELLER:`,-1),c[942]||=i(` Hey, let's bring the rest of these down to the truck.`,-1),c[943]||=a(`blockquote`,null,[a(`p`,null,`嘿，让我们把剩下的带到卡车上。`)],-1),c[944]||=a(`p`,null,`[Everyone except Joey and Chandler leave.]`,-1),c[945]||=a(`blockquote`,null,[a(`p`,null,`[除了乔伊和钱德勒，所有人都离开了。]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/218.mp3`}),c[946]||=i(),c[947]||=a(`strong`,null,`CHANDLER BING:`,-1),c[948]||=i(` So, uhh, em, you want me to uh, give you a hand with the foosball table?`,-1),c[949]||=a(`blockquote`,null,[a(`p`,null,`那么，嗯，嗯，你想让我帮你拿一下足球桌吗？`)],-1),r(p,{src:`/audio/friends/S02/S02E16/219.mp3`}),c[950]||=i(),c[951]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[952]||=i(` Naa, you keep it, you need the practice.`,-1),c[953]||=a(`blockquote`,null,[a(`p`,null,`娜娜，你留着吧，你需要练习。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/220.mp3`}),c[954]||=i(),c[955]||=a(`strong`,null,`CHANDLER BING:`,-1),c[956]||=i(` Thanks.`,-1),c[957]||=a(`blockquote`,null,[a(`p`,null,`谢谢。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/221.mp3`}),c[958]||=i(),c[959]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[960]||=i(` So, I guess this is it.`,-1),c[961]||=a(`blockquote`,null,[a(`p`,null,`那么，我想就是这个了。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/222.mp3`}),c[962]||=i(),c[963]||=a(`strong`,null,`CHANDLER BING:`,-1),c[964]||=i(` Yeah, right, yeah, I guess so.`,-1),c[965]||=a(`blockquote`,null,[a(`p`,null,`是的，对，是的，我想是的。`)],-1),c[966]||=a(`p`,null,`[Joey walks to the door. He stops, turns around.]`,-1),c[967]||=a(`blockquote`,null,[a(`p`,null,`[乔伊走到门口。他停下来，转过身来。]`)],-1),r(p,{src:`/audio/friends/S02/S02E16/223.mp3`}),c[968]||=i(),c[969]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[970]||=i(` Listen, uh, I don't know when I'm gonna see you again.`,-1),c[971]||=a(`blockquote`,null,[a(`p`,null,`听着，我不知道什么时候能再见到你。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/224.mp3`}),c[972]||=i(),c[973]||=a(`strong`,null,`CHANDLER BING:`,-1),c[974]||=i(` Well, I'm guessing uh, tonight at the coffee house.`,-1),c[975]||=a(`blockquote`,null,[a(`p`,null,`嗯，我猜，呃，今晚在咖啡馆。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/225.mp3`}),c[976]||=i(),c[977]||=a(`strong`,null,`JOEY TRIBBIANI:`,-1),c[978]||=i(` Right, yeah. OK. Um, take care.`,-1),c[979]||=a(`blockquote`,null,[a(`p`,null,`对，是的。好啊嗯，保重。`)],-1),r(p,{src:`/audio/friends/S02/S02E16/226.mp3`}),c[980]||=t(` <strong>CHANDLER BING:</strong> Yeah.<blockquote><p>是的。</p></blockquote><p>[Joey walks out and after a few seconds comes back in and gives Chandler a big hug. He then leaves for good and Chandler is left alone in his apartment.]</p><blockquote><p>[乔伊走出去，几秒钟后回来，给了钱德勒一个大大的拥抱。然后他就永远离开了，钱德勒一个人留在他的公寓里。]</p></blockquote><p>CLOSING CREDITS</p><blockquote><p>期末学分</p></blockquote><p>END</p><blockquote><p>结束</p></blockquote><p>contrl08.gif (14783 bytes)</p><blockquote><p>contrl08.gif（14783字节）</p></blockquote>`,12)])}var d=s(l,[[`render`,u]]);export{c as _pageData,d as default};